# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#1e3a8a" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">النُّبُوَّةُ وَالرِّسَالَةُ (PEYGAMBERLİK, ELÇİLİK VE 25 PEYGAMBER)</text>\n\n  <rect x="15" y="54" width="325" height="190" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="325" height="26" fill="#2563eb" rx="6"/>\n  <text x="177" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">1. NÜBÜVVET VE RİSALET KAVRAMLARI</text>\n  <text x="25" y="95" fill="#1e3a8a" font-size="9.5" font-weight="bold">• Yaratılış Gayesi (Zâriyât, 56):</text>\n  <text x="29" y="110" fill="#1d4ed8" font-size="9.5" font-weight="bold">«وَمَا خَلَقْتُ الْجِنَّ وَالْإِنْسَ إِلَّا لِيَعْبُدُونِ»</text>\n  <text x="25" y="128" fill="#1e3a8a" font-size="9.5" font-weight="bold">• النُّبُوَّة (en-Nübüvvetü):</text>\n  <text x="29" y="142" fill="#1e293b" font-size="9">اختيارُ اللَّهِ لِعَبْدٍ مِنْ عِبَادِهِ بِإِنْزَالِ الوَحْيِ عَلَيْهِ</text>\n  <text x="29" y="155" fill="#1e293b" font-size="8.5">(Allah\'ın kullarından birini vahiy indirerek seçmesidir.)</text>\n  <text x="25" y="172" fill="#1e3a8a" font-size="9.5" font-weight="bold">• الرَّسُول وَالرِّسَالَة (er-Resûl ve\'r-Risâle):</text>\n  <text x="29" y="186" fill="#1e293b" font-size="9">فَإِذَا أَمَرَ اللَّهُ هَذَا النَّبِيَّ بِتَبْلِيغِ الشَّرِيعَةِ كَانَ رَسُولًا</text>\n  <text x="29" y="200" fill="#1e293b" font-size="8.5">Risalet çabayla kazanılmaz (لَا تُكْتَسَبُ بِجُهْدٍ);</text>\n  <text x="29" y="214" fill="#1e293b" font-size="8.5">Allah\'ın dilediğine verdiği büyük bir lütuftur (فَضْلٌ عَظِيمٌ).</text>\n  <text x="29" y="232" fill="#1d4ed8" font-size="9" font-weight="bold">«اللَّهُ أَعْلَمُ حَيْثُ يَجْعَلُ رِسَالَتَهُ» (En\'âm, 124)</text>\n\n  <rect x="360" y="54" width="325" height="190" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5" rx="8"/>\n  <rect x="360" y="54" width="325" height="26" fill="#16a34a" rx="6"/>\n  <text x="522" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">2. KUR\'AN\'DA PEYGAMBERLER VE TEVHİD</text>\n  <text x="370" y="95" fill="#14532d" font-size="9.5" font-weight="bold">• Kur\'an\'da Zikredilen Peygamber Sayısı:</text>\n  <text x="374" y="111" fill="#15803d" font-size="9.5" font-weight="bold">عَدَدُ الرُّسُلِ فِي القُرْآنِ الكَرِيمِ خَمْسَةٌ وَعِشْرُونَ (25) رَسُولًا</text>\n  <text x="374" y="126" fill="#1e293b" font-size="9">(Kur\'an-ı Kerim\'de 25 peygamberin ismi geçmektedir.)</text>\n  <text x="370" y="145" fill="#14532d" font-size="9.5" font-weight="bold">• En\'âm Suresi 83-86. Ayetler:</text>\n  <text x="374" y="159" fill="#1e293b" font-size="9">Hz. İbrahim, İshak, Yakub, Nuh, Davud, Süleyman,</text>\n  <text x="374" y="172" fill="#1e293b" font-size="9">Eyyub, Yusuf, Musa, Harun, Zekeriyya, Yahya, İsa,</text>\n  <text x="374" y="185" fill="#1e293b" font-size="9">İlyas, İsmail, Elyesa, Yunus ve Lut (18 peygamber).</text>\n  <text x="370" y="204" fill="#14532d" font-size="9.5" font-weight="bold">• Ortak Tevhid Çağrısı:</text>\n  <text x="374" y="220" fill="#15803d" font-size="10" font-weight="bold">«اعْبُدُوا اللَّهَ مَا لَكُمْ مِنْ إِلَٰهٍ غَيْرُهُ»</text>\n  <text x="374" y="234" fill="#1e293b" font-size="8.5">("Allah\'a kulluk edin, sizin O\'ndan başka ilahınız yoktur.")</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#7c2d12" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">أُولُو العَزْمِ مِنَ الرُّسُلِ (ULU\'L-AZM PEYGAMBERLER VE GÖREVLERİ)</text>\n\n  <rect x="15" y="54" width="670" height="92" fill="#fff7ed" stroke="#f97316" stroke-width="1.5" rx="8"/>\n  <text x="350" y="73" fill="#9a3412" font-size="11" font-weight="bold" text-anchor="middle">BEŞ BÜYÜK ULU\'L-AZM PEYGAMBER (أُولُو العَزْمِ مِنَ الرُّسُلِ الخَمْسَةُ — Ahzâb, 7 / Şûrâ, 13)</text>\n  \n  <rect x="28" y="84" width="120" height="50" fill="#ffedd5" stroke="#ea580c" stroke-width="1.2" rx="6"/>\n  <text x="88" y="105" fill="#7c2d12" font-size="11" font-weight="bold" text-anchor="middle">١. نُوحٌ (ع)</text>\n  <text x="88" y="122" fill="#1e293b" font-size="9" text-anchor="middle">Hz. Nuh (as)</text>\n\n  <rect x="158" y="84" width="120" height="50" fill="#ffedd5" stroke="#ea580c" stroke-width="1.2" rx="6"/>\n  <text x="218" y="105" fill="#7c2d12" font-size="11" font-weight="bold" text-anchor="middle">٢. إِبْرَاهِيمُ (ع)</text>\n  <text x="218" y="122" fill="#1e293b" font-size="9" text-anchor="middle">Hz. İbrahim (as)</text>\n\n  <rect x="288" y="84" width="120" height="50" fill="#ffedd5" stroke="#ea580c" stroke-width="1.2" rx="6"/>\n  <text x="348" y="105" fill="#7c2d12" font-size="11" font-weight="bold" text-anchor="middle">٣. مُوسَى (ع)</text>\n  <text x="348" y="122" fill="#1e293b" font-size="9" text-anchor="middle">Hz. Musa (as)</text>\n\n  <rect x="418" y="84" width="120" height="50" fill="#ffedd5" stroke="#ea580c" stroke-width="1.2" rx="6"/>\n  <text x="478" y="105" fill="#7c2d12" font-size="11" font-weight="bold" text-anchor="middle">٤. عِيسَى (ع)</text>\n  <text x="478" y="122" fill="#1e293b" font-size="9" text-anchor="middle">Hz. İsa (as)</text>\n\n  <rect x="548" y="84" width="125" height="50" fill="#fef08a" stroke="#ca8a04" stroke-width="1.5" rx="6"/>\n  <text x="610" y="105" fill="#854d0e" font-size="11" font-weight="bold" text-anchor="middle">٥. مُحَمَّدٌ (ﷺ)</text>\n  <text x="610" y="122" fill="#713f12" font-size="8.5" font-weight="bold" text-anchor="middle">أَفْضَلُ الرُّسُلِ (En Faziletlisi)</text>\n\n  <rect x="15" y="156" width="670" height="90" fill="#fefce8" stroke="#eab308" stroke-width="1.5" rx="8"/>\n  <text x="350" y="176" fill="#713f12" font-size="11" font-weight="bold" text-anchor="middle">PEYGAMBERLERİN TEMEL GÖREVLERİ (وَظَائِفُ الأَنْبِيَاءِ وَالرُّسُلِ)</text>\n  <text x="30" y="198" fill="#1e293b" font-size="9.5">• <tspan font-weight="bold" fill="#854d0e">التَّبْلِيغ (et-Teblîğ):</tspan> İlahi vahyi ve şeriatı insanlara eksiksiz ulaştırmak.</text>\n  <text x="30" y="216" fill="#1e293b" font-size="9.5">• <tspan font-weight="bold" fill="#854d0e">مُبَشِّرِينَ وَمُنْذِرِينَ (Tebşîr ve İnzâr):</tspan> Müminleri cennetle müjdeleyici, inkârcıları uyarıcı olmak.</text>\n  <text x="30" y="234" fill="#1e293b" font-size="9.5">• <tspan font-weight="bold" fill="#854d0e">هِدَايَةُ البَشَرِ وَأُسْوَةٌ حَسَنَةٌ:</tspan> İnsanlığın hidayetine rehberlik etmek ve güzel ahlakta en güzel örnek olmak.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="system-ui, -apple-system, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <rect x="10" y="10" width="680" height="34" fill="#0f766e" rx="8"/>\n  <text x="350" y="32" fill="#ffffff" font-size="13" font-weight="bold" text-anchor="middle">القَوَاعِدُ: الفِعْلُ المُجَرَّدُ وَالفِعْلُ المَزِيدُ (YALIN VE TÜREMİŞ/EKLİ FİİLLER)</text>\n\n  <rect x="15" y="54" width="315" height="190" fill="#f0fdfa" stroke="#14b8a6" stroke-width="1.5" rx="8"/>\n  <rect x="15" y="54" width="315" height="26" fill="#0d9488" rx="6"/>\n  <text x="172" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">١. الفِعْلُ المُجَرَّدُ (YALIN / KÖK FİİL)</text>\n  <text x="25" y="94" fill="#115e59" font-size="9" font-weight="bold">مَا كَانَتْ جَمِيعُ أَحْرُفِهِ أَصْلِيَّةً وَلَيْسَ مَعَهَا حَرْفٌ زَائِدٌ</text>\n  <text x="25" y="108" fill="#1e293b" font-size="8.5">(Bütün harfleri asli/kök olan, ziyade harf bulunmayan fiil)</text>\n  \n  <text x="25" y="128" fill="#0f766e" font-size="9.5" font-weight="bold">• المُجَرَّدُ الثُّلَاثِيُّ (3 Kök Harfli - Sülâsî Mücerred):</text>\n  <text x="29" y="144" fill="#1e293b" font-size="9.5">كَتَبَ ، قَامَ ، كَسَبَ ، وَهَبَ ، سَعَى ، شَرَعَ</text>\n  <text x="29" y="160" fill="#1e293b" font-size="9.5">خَتَمَ ، كَفَرَ ، خَلَقَ ، بَعَثَ ، عَبَدَ ، أَخَذَ ، حَفِظَ</text>\n\n  <text x="25" y="182" fill="#0f766e" font-size="9.5" font-weight="bold">• المُجَرَّدُ الرُّبَاعِيُّ (4 Kök Harfli - Rubâî Mücerred):</text>\n  <text x="29" y="198" fill="#1e293b" font-size="9.5">بَعْثَرَ ، وَسْوَسَ ، زَلْزَلَ ، دَحْرَجَ ، طَمْأَنَ</text>\n  <text x="29" y="218" fill="#115e59" font-size="8.5">* Emir çekimi örnekleri: أَخَذَ -&gt; يَأْخُذُ -&gt; خُذْ | حَفِظَ -&gt; يَحْفَظُ -&gt; اِحْفَظْ</text>\n\n  <rect x="345" y="54" width="340" height="190" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5" rx="8"/>\n  <rect x="345" y="54" width="340" height="26" fill="#2563eb" rx="6"/>\n  <text x="515" y="71" fill="#ffffff" font-size="10.5" font-weight="bold" text-anchor="middle">٢. الفِعْلُ المَزِيدُ (ZİYADE HARFLİ / TÜREMİŞ FİİL)</text>\n  <text x="355" y="94" fill="#1e3a8a" font-size="9" font-weight="bold">مَا كَانَ مَعَ أَحْرُفِهِ الأَصْلِيَّةِ أَحْرُفٌ زَائِدَةٌ (سَأَلْتُمُونِيهَا)</text>\n  \n  <text x="355" y="112" fill="#1d4ed8" font-size="9.2" font-weight="bold">• Sülâsî Mezîd (1 Harf Ekli / الرُّبَاعِيّ):</text>\n  <text x="359" y="126" fill="#1e293b" font-size="9">أَفْعَلَ (أَرْسَلَ، أَنْزَلَ، أَنْذَرَ، أَكْرَمَ، أَعْطَى) | فَعَّلَ (عَلَّمَ، بَشَّرَ، وَصَّى، فَضَّلَ)</text>\n  <text x="359" y="140" fill="#1e293b" font-size="9">فَاعَلَ (كَاتَبَ، سَاعَدَ، شَاهَدَ، جَاهَدَ، حَاسَبَ)</text>\n\n  <text x="355" y="158" fill="#1d4ed8" font-size="9.2" font-weight="bold">• Sülâsî Mezîd (2 Harf Ekli / الخُمَاسِيّ):</text>\n  <text x="359" y="172" fill="#1e293b" font-size="9">اِفْتَعَلَ (اِكْتَسَبَ، اِجْتَمَعَ، اِقْتَصَرَ، اِحْتَاجَ) | اِنْفَعَلَ (اِنْطَلَقَ، اِنْكَسَرَ)</text>\n  <text x="359" y="186" fill="#1e293b" font-size="9">تَفَعَّلَ (تَعَلَّمَ) | تَفَاعَلَ (تَعَاوَنَ)</text>\n\n  <text x="355" y="204" fill="#1d4ed8" font-size="9.2" font-weight="bold">• Sülâsî Mezîd (3 Harf Ekli / السُّدَاسِيّ) &amp; Rubâî Mezîd:</text>\n  <text x="359" y="218" fill="#1e293b" font-size="9">اِسْتَفْعَلَ (اِسْتَقَامَ، اِسْتَغْفَرَ، اِسْتَخْرَجَ)</text>\n  <text x="359" y="232" fill="#1e293b" font-size="9">تَفَعْلَلَ (تَدَحْرَجَ، تَزَلْزَلَ) | اِفْعَلَلَّ (اِطْمَأَنَّ، اِقْشَعَرَّ)</text>\n</svg>']

def uygula(v):
    for i, s in enumerate(SVGS):
        if i < len(v.get('bolumler', [])):
            v['bolumler'][i]['gorsel'] = s
